ion="<?= url('/mobil/'.$car['id'].'/favorit') ?>"><?= csrf_field() ?><button class="btn btn-outline btn-block"><?= $fav?'♥ Hapus dari Favorit':'♡ Simpan Favorit' ?></button></form><?php endif; ?></aside></section>
